{"content":"/**
/**
 * RFC 4180 style CSV reader and writer with a configurable delimiter and quote
 * character, byte-order-mark handling and exact positions on failure.
 */

/** Failure raised by the CSV reader and writer. */
export class CsvError extends Error {
  /**
   * @param {string} message reason, without positional information
   * @param {number} [line] 1-based line the failure was found on
   * @param {number} [column] 1-based column, counted in UTF-16 code units
   */
  constructor(message, line, column) {
    super(message);
    this.name = 'CsvError';
    this.line = line;
    this.column = column;
  }
}

/**
 * Read a CSV document into records.
 *
 * @param {string} text document source
 * @param {{ delimiter?: string, quote?: string, strictWidth?: boolean }} [options] dialect and width policy
 * @returns {string[][]} one array of field values per record
 */
export function parse(text, options = {}) {
  if (typeof text !== 'string') {
    throw new CsvError('input must be a string');
  }

  const delimiter = options.delimiter ?? ',';
  const quote = options.quote ?? '"';
  const strictWidth = options.strictWidth ?? false;

  if (typeof delimiter !== 'string' || delimiter.length !== 1) {
    throw new CsvError('delimiter must be a single character');
  }
  if (typeof quote !== 'string' || quote.length !== 1) {
    throw new CsvError('quote must be a single character');
  }
  if (delimiter === quote) {
    throw new CsvError('delimiter and quote must differ');
  }
  if (delimiter === '\n' || delimiter === '\r' || quote === '\n' || quote === '\r') {
    throw new CsvError('delimiter and quote must not be line terminators');
  }

  // Drop leading BOM
  if (text.startsWith('\uFEFF')) {
    text = text.slice(1);
  }

  const records = [];
  let currentRecord = [];
  let currentField = '';
  let inQuotes = false;
  let i = 0;
  let line = 1;
  let column = 1;

  while (i < text.length) {
    const ch = text[i];

    if (inQuotes) {
      if (ch === quote) {
        // Check if next character is also a quote (escaped quote)
        if (i + 1 < text.length && text[i + 1] === quote) {
          currentField += quote;
          i += 2;
          column += 2;
          continue;
        } else {
          // Closing quote
          inQuotes = false;
          i++;
          column++;

          // After closing quote, only delimiter, line terminator, or end is allowed
          if (i < text.length) {
            const nextCh = text[i];
            if (nextCh !== delimiter && nextCh !== '\n' && nextCh !== '\r') {
              throw new CsvError(`unexpected character after closing quote: ${nextCh}`, line, column);
            }
          }
          continue;
        }
      } else {
        // Inside quoted field
        currentField += ch;
        if (ch === '\n') {
          line++;
          column = 1;
        } else if (ch === '\r') {
          // Handle CR - if followed by LF, consume both
          if (i + 1 < text.length && text[i + 1] === '\n') {
            line++;
            column = 1;
            i += 2;
            continue;
          } else {
            line++;
            column = 1;
          }
        } else {
          column++;
        }
        i++;
        continue;
      }
    } else {
      // Not in quotes
      if (ch === quote) {
        // Opening quote - only valid at start of field
        if (currentField.length > 0) {
          throw new CsvError('unexpected character after closing quote: ', line, column);
        }
        inQuotes = true;
        i++;
        column++;
        continue;
      } else if (ch === delimiter) {
        // End of field
        currentRecord.push(currentField);
        currentField = '';
        i++;
        column++;
        continue;
      } else if (ch === '\n' || ch === '\r') {
        // End of record
        currentRecord.push(currentField);
        currentField = '';
        records.push(currentRecord);
        currentRecord = [];

        // Handle CRLF
        if (ch === '\r' && i + 1 < text.length && text[i + 1] === '\n') {
          i += 2;
        } else {
          i++;
        }

        line++;
        column = 1;

        // Skip empty lines at end that don't create new records
        if (i >= text.length) {
          break;
        }
        continue;
      } else {
        // Regular character
        currentField += ch;
        i++;
        column++;
        continue;
      }
    }
  }

  // Handle last field and record
  if (inQuotes) {
    throw new CsvError('unterminated quoted field', line, column - currentField.length);
  }

  currentRecord.push(currentField);
  if (currentRecord.length > 0 || text.length > 0) {
    records.push(currentRecord);
  }

  // Handle strictWidth
  if (strictWidth && records.length > 1) {
    const expectedWidth = records[0].length;
    for (let i = 1; i < records.length; i++) {
      if (records[i].length !== expectedWidth) {
        throw new CsvError(`expected ${expectedWidth} fields, got ${records[i].length}`, i + 1, 1);
      }
    }
  }

  return records;
}

/**
 * Serialise one field, quoting it when the dialect requires it.
 *
 * @param {unknown} value field value
 * @param {{ delimiter?: string, quote?: string, alwaysQuote?: boolean }} [options] dialect and quoting policy
 * @returns {string} the field as it appears in the document
 */
export function escapeField(value, options = {}) {
  if (value === null || value === undefined) {
    value = '';
  } else if (typeof value === 'boolean' || typeof value === 'number') {
    if (!isFinite(value)) {
      throw new CsvError(`unsupported field value: ${value}`);
    }
    value = String(value);
  } else if (typeof value !== 'string') {
    throw new CsvError(`unsupported field type: ${typeof value}`);
  }

  const delimiter = options.delimiter ?? ',';
  const quote = options.quote ?? '"';
  const alwaysQuote = options.alwaysQuote ?? false;

  if (typeof delimiter !== 'string' || delimiter.length !== 1) {
    throw new CsvError('delimiter must be a single character');
  }
  if (typeof quote !== 'string' || quote.length !== 1) {
    throw new CsvError('quote must be a single character');
  }
  if (delimiter === quote) {
    throw new CsvError('delimiter and quote must differ');
  }
  if (delimiter === '\n' || delimiter === '\r' || quote === '\n' || quote === '\r') {
    throw new CsvError('delimiter and quote must not be line terminators');
  }

  // Check if field needs quoting
  const needsQuote = alwaysQuote ||
    value.includes(delimiter) ||
    value.includes(quote) ||
    value.includes('\n') ||
    value.includes('\r') ||
    value.includes('\uFEFF');

  if (!needsQuote) {
    return value;
  }

  // Escape quotes by doubling them
  let escaped = value.replace(new RegExp(quote.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'g'), quote + quote);
  return quote + escaped + quote;
}

/**
 * Write records as a CSV document.
 *
 * @param {unknown[][]} rows records to write
 * @param {{ delimiter?: string, quote?: string, newline?: string, bom?: boolean, alwaysQuote?: boolean }} [options]
 *   dialect, terminator and byte-order-mark policy
 * @returns {string} the document, with a terminator after every record
 */
export function stringify(rows, options = {}) {
  if (!Array.isArray(rows)) {
    throw new CsvError('rows must be an array');
  }

  const delimiter = options.delimiter ?? ',';
  const quote = options.quote ?? '"';
  const newline = options.newline ?? '\r\n';
  const bom = options.bom ?? false;
  const alwaysQuote = options.alwaysQuote ?? false;

  if (typeof delimiter !== 'string' || delimiter.length !== 1) {
    throw new CsvError('delimiter must be a single character');
  }
  if (typeof quote !== 'string' || quote.length !== 1) {
    throw new CsvError('quote must be a single character');
  }
  if (delimiter === quote) {
    throw new CsvError('delimiter and quote must differ');
  }
  if (delimiter === '\n' || delimiter === '\r' || quote === '\n' || quote === '\r') {
    throw new CsvError('delimiter and quote must not be line terminators');
  }
  if (newline !== '\n' && newline !== '\r\n' && newline !== '\r') {
    throw new CsvError('newline must be a line terminator');
  }

  if (rows.length === 0) {
    return bom ? '\uFEFF' : '';
  }

  let result = '';
  if (bom) {
    result += '\uFEFF';
  }

  for (let i = 0; i < rows.length; i++) {
    const row = rows[i];
    if (!Array.isArray(row)) {
      throw new CsvError(`record ${i} is not an array`);
    }
    if (row.length === 0) {
      throw new CsvError(`record ${i} has no fields`);
    }

    const escapedFields = row.map(field => escapeField(field, { delimiter, quote, alwaysQuote }));
    result += escapedFields.join(delimiter);
    result += newline;
  }

  return result;
}","file_path":"src/csv.js"}

